(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.04-t*0.5)*8 + Math.cos((y+wy1)*0.035+t*0.4)*6;
  const wy2 = Math.cos((y+wy1)*0.04+t*0.45)*8 + Math.sin((x+wx1)*0.03-t*0.55)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*55,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+1)*85,200+Math.sin(t*0.75+4)*65,0.065,2.4,1.05],
    [200+Math.sin(t*0.7+6)*60,30+Math.cos(t*0.5+5)*45,0.095,1.8,0.9],
    [300+Math.cos(t*0.42+2)*75,100+Math.sin(t*0.58+3)*55,0.075,2.2,1.1]
  ];
  let aS=0,iS=0,pS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    pS+=Math.sin(d*f*1.3-t*sp*0.8+3.0)*w*0.5;
  }
  const act=aS/10,inh=iS/10,pat=pS/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.06-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.07+ang*2-t*2.0)*0.2;
  const cX=sx*0.08,cY=sy*0.08,cix=Math.floor(cX),ciy=Math.floor(cY);
