    const py=ny+Math.cos(nx*2.1+ny*1.5+t*0.6)*0.4;
    const cd=Math.sqrt((cX-px)**2+(cY-py)**2);
    if(cd<minD)minD=cd;
  }
  const voronoi=Math.sin(minD*Math.PI*2-t*1.5)*0.4;
  const rings=Math.sin(dist*0.08-t*1.2)*0.3+Math.sin(dist*0.12+t*0.9)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+voronoi*0.4+rings*0.2+pat*0.3)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const detail=Math.sin(sx*0.3+t*2)*Math.sin(sy*0.25-t*1.8)*0.1;
  const blend=reaction*0.6+cell*0.2+voronoi*0.15+detail*0.05;
  const v=blend*0.5+0.5;
  const pal=[[5,12,55],[12,55,95],[18,105,130],[30,160,145],[120,190,120],[200,195,80],[220,150,60],[200,90,60],[160,50,70],[100,30,80],[50,20,70],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const glow=Math.exp(-dist*0.008)*0.15+1.0;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*glow)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*glow)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*glow)|0];
}
